package pe.nexo.store.product;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.*;
@Entity@Table(name="products")public class Product{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(unique=true)private String sku;@Column(nullable=false)private String name;@Column(nullable=false)private String category;@Column(nullable=false,precision=10,scale=2)private BigDecimal price;@Column(precision=10,scale=2)private BigDecimal originalPrice;@Column(nullable=false)private Double rating;@Column(nullable=false)private String image;private String tag;@Column(nullable=false)private String spec;@ElementCollection(fetch=FetchType.EAGER)@CollectionTable(name="product_specifications",joinColumns=@JoinColumn(name="product_id"))@MapKeyColumn(name="spec_key")@Column(name="spec_value")private Map<String,String>specifications=new LinkedHashMap<>();private Integer stock;@Column(nullable=false)private boolean inStock;protected Product(){}public Product(Long id,String name,String category,BigDecimal price,BigDecimal originalPrice,Double rating,String image,String tag,String spec,boolean inStock){this(id,id==null?null:"NEXO-"+id,name,category,price,originalPrice,rating,image,tag,spec,Map.of(),inStock?20:0,inStock);}public Product(Long id,String sku,String name,String category,BigDecimal price,BigDecimal originalPrice,Double rating,String image,String tag,String spec,Map<String,String>specifications,Integer stock,boolean inStock){this.id=id;update(sku,name,category,price,originalPrice,rating,image,tag,spec,specifications,stock,inStock);}public void update(String sku,String name,String category,BigDecimal price,BigDecimal originalPrice,Double rating,String image,String tag,String spec,Map<String,String>specifications,Integer stock,boolean inStock){this.sku=sku==null||sku.isBlank()?null:sku.trim().toUpperCase(Locale.ROOT);this.name=name.trim();this.category=category;this.price=price;this.originalPrice=originalPrice;this.rating=rating;this.image=image;this.tag=tag;this.spec=spec;this.specifications=new LinkedHashMap<>(specifications==null?Map.of():specifications);this.stock=stock==null?0:stock;this.inStock=inStock&&this.stock>0;}public void reserve(int quantity){if(!inStock||stock==null||stock<quantity)throw new IllegalStateException(name+" no tiene stock suficiente");stock-=quantity;if(stock==0)inStock=false;}public Long getId(){return id;}public String getSku(){return sku;}public String getName(){return name;}public String getCategory(){return category;}public BigDecimal getPrice(){return price;}public BigDecimal getOriginalPrice(){return originalPrice;}public Double getRating(){return rating;}public String getImage(){return image;}public String getTag(){return tag;}public String getSpec(){return spec;}public Map<String,String>getSpecifications(){return specifications;}public Integer getStock(){return stock;}public boolean isInStock(){return inStock;}}
